const body = $json.body ?? $json;
const pedido_id = body.pedido_id || body.orderId;
const pizzaria_id = body.pizzaria_id || body.pizzeriaId;
if (!pedido_id || !pizzaria_id) {
  return [{ json: { skip: true, reason: 'missing_ids' } }];
}
return [{ json: { skip: false, pedido_id, pizzaria_id } }];

const row = $json;
const statusMsg = row.mensagens_status?.entregue || row.mensagem_entregue || 'Pedido entregue com sucesso! Obrigado pela preferência. 🍕';

// Substitui variáveis disponíveis na mensagem customizada
let mensagem = String(statusMsg)
  .replace(/\{nome_cliente\}/g, row.cliente_nome || 'cliente')
  .replace(/\{numero_pedido\}/g, String(row.numero_pedido || ''))
  .replace(/\{nome_pizzaria\}/g, row.pizzaria_nome || '')
  .replace(/\{valor_total\}/g, Number(row.valor_total||0).toFixed(2))
  .replace(/\{total_pedidos\}/g, String(row.total_pedidos || 1));

// Adiciona toque especial se for cliente recorrente
if (Number(row.total_pedidos) > 1) {
  mensagem += `\n\nVocê já fez ${row.total_pedidos} pedidos com a gente. Obrigado pela parceria! 🙏`;
}

return [{
  json: {
    mensagem,
    instancia: row.instancia,
    telefone: row.cliente_telefone,
    pedido_id: row.id,
    numero_pedido: row.numero_pedido
  }
}];
